            let work = self.begin_reply_enrichment()?;
            let revision = self.inner.store.observation_revision()?;
            let thread = self
                .inner
                .provider
                .get_thread(&r#ref.conversation_id, &work.cancel)?
                .ok_or(MailError::NotFound)?;
