//! Wire-facing error type. Rust owns the DTO shape; the Tauri shell rejects
//! promises with this exact object (camelCase keys, snake_case discriminants).

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Typed error surfaced across IPC. `kind` is the discriminant; payloads stay flat.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS, thiserror::Error)]
#[serde(tag = "kind", rename_all = "snake_case")]
#[ts(rename_all = "snake_case")]
pub enum MailError {
    #[error("referenced account, conversation or operation was not found")]
    NotFound,
    #[error("invalid request field: {field}")]
    InvalidRequest {
        /// Name of the offending request field (camelCase DTO name).
        field: String,
    },
    #[error("request id was already used with a different command payload")]
    RequestIdConflict,
    #[error("local storage is unavailable; the operation was not accepted")]
    StorageUnavailable,
    #[error("another writer owns this profile; refusing concurrent access")]
    ProfileInUse,
    #[error("Gmail mode is read-only")]
    ReadOnly,
    #[error("Google desktop OAuth client is not configured")]
    NotConfigured,
    #[error("authentication is required")]
    AuthRequired,
    #[error("authentication or synchronization was cancelled")]
    AuthCancelled,
    #[error("authentication failed")]
    AuthFailed,
    #[error("secure credential storage is unavailable")]
    SecretsUnavailable,
    #[error("network is unavailable")]
    NetworkUnavailable,
    #[error("provider rate limit reached")]
    RateLimited,
    #[error("provider is unavailable")]
    ProviderUnavailable,
    #[error("provider returned unsupported or invalid data")]
    InvalidProviderResponse,
    #[error("another account operation is in progress")]
    Busy,
    #[error("verified mailbox modification permission is required")]
    PermissionRequired,
    #[error("the provider rejected the mailbox operation")]
    ProviderRejected,
    #[error("the remote outcome is uncertain and must be reconciled")]
    OutcomeUnknown,
    #[error("draft revision conflict; current revision is {current_revision}")]
    DraftConflict {
        #[serde(rename = "currentRevision")]
        current_revision: u32,
    },
    #[error("complete and safe reply context is unavailable")]
    ReplyUnavailable,
    #[error("the last action cannot be undone")]
    UndoUnavailable {
        /// Typed eligibility failure (docs/ux-04-trustworthy-undo.md §3.2).
        reason: crate::dto::UndoUnavailableReason,
    },
}

/// Fake-provider outcome. `Cancelled` is not a failure: the operation stays
/// durably in `applying` and is requeued on the next launch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProviderError {
    /// Definite provider-side unavailability; the operation is marked `failed`.
    Unavailable,
    /// Definite provider rejection; the operation is marked `failed`.
    Rejected,
    /// Shutdown cancellation; the operation stays durable for recovery.
    Cancelled,
}

impl ProviderError {
    /// Wire-facing failure discriminant for a definite failure. `Cancelled`
    /// never produces an `OperationFailure`; it is recovered instead.
    pub fn failure_kind(self) -> Option<&'static str> {
        match self {
            ProviderError::Unavailable => Some("provider_unavailable"),
            ProviderError::Rejected => Some("provider_rejected"),
            ProviderError::Cancelled => None,
        }
    }
}
//! One diagnosable log line per storage failure, with no mailbox data.
//!
//! Every storage failure still surfaces as [`MailError::StorageUnavailable`]; the wire error
//! is unchanged. What this module adds is a record of *why*, so a failure can be diagnosed
//! from a log. The privacy promise is enforced structurally: a line is built only from
//! static strings, the call site's `file:line` and the numeric SQLite result codes. Display
//! text of an underlying error is never read, because SQLite messages can quote data such as
//! constraint-violating values or SQL fragments.

use std::panic::Location;

use crate::error::MailError;

/// Log target used for every line; the shell's logger filters on it.
pub const LOG_TARGET: &str = "mail_core::storage";

/// What is known about a failure, limited to values that cannot contain mailbox data.
pub(crate) struct Cause {
    /// Static tag naming the kind of failure.
    pub(crate) kind: &'static str,
    /// SQLite primary result code name and extended code, when the cause is a SQLite error.
    pub(crate) sqlite: Option<(&'static str, i32)>,
}

impl Cause {
    const fn plain(kind: &'static str) -> Self {
        Cause { kind, sqlite: None }
    }
}

/// Classifies an underlying error without reading its message.
pub(crate) trait StorageCause {
    fn cause(&self) -> Cause;
}

impl StorageCause for rusqlite::Error {
    fn cause(&self) -> Cause {
        match self {
            rusqlite::Error::SqliteFailure(error, _) => Cause {
                kind: "sqlite",
                sqlite: Some((code_name(error.code), error.extended_code)),
            },
            // Prepare-time failures carry the code plus the SQL text and an offset. Only the
            // numeric code is read; the SQL and message are never touched.
            rusqlite::Error::SqlInputError { error, .. } => Cause {
                kind: "sqlite",
                sqlite: Some((code_name(error.code), error.extended_code)),
            },
            // Other variants carry no result code; their payloads may hold
            // column names or values, so only the variant is recorded.
            rusqlite::Error::QueryReturnedNoRows => Cause::plain("sqlite_no_rows"),
            rusqlite::Error::FromSqlConversionFailure(..) => Cause::plain("sqlite_from_sql"),
            rusqlite::Error::InvalidColumnType(..) => Cause::plain("sqlite_column_type"),
            rusqlite::Error::InvalidParameterCount(..) => Cause::plain("sqlite_parameter_count"),
            _ => Cause::plain("sqlite_other"),
        }
    }
}

