/// Classifies an underlying error without reading its message.
pub(crate) trait StorageCause {
    fn cause(&self) -> Cause;
}

impl StorageCause for rusqlite::Error {
    fn cause(&self) -> Cause {
        match self {
            rusqlite::Error::SqliteFailure(error, _) => Cause {
                kind: "sqlite",
