                    assert!(member.operation_ids.is_empty());
                    let has_compensation: bool = conn
                        .query_row(
                            "SELECT EXISTS(SELECT 1 FROM operations WHERE undo_of = ?1)",
                            params![child_id],
                            |row| row.get(0),
                        )
                        .unwrap();
                    assert!(!has_compensation, "skipped members are never compensated");
                }
            }
        }
    }
}

