    assert_eq!(
        second.conversations[0].conversation_ref.conversation_id,
        "bounded-100"
    );
    assert_eq!(second.next_cursor, None);
    drop(conn);
    drop(core);
    std::fs::remove_dir_all(dir).unwrap();
}
