            synthetic: provider.clone(),
            provider,
            clock,
            dir,
        }
    }

    /// Stops the core and reopens the SAME profile with a NEW provider object,
    /// proving provider facts are durable rather than held in memory.
    pub fn reopen(&mut self) {
        self.core.stop();
        let provider = new_provider(self.dir.path());
        let core = open_core_on(self.dir.path(), provider.clone(), &self.clock);
        self.core = core;
        self.synthetic = provider.clone();
        self.provider = provider;
