#[test]
fn paused_provider_does_not_hold_the_db_lock_and_claims_do_not_overlap() {
    let s = Synthetic::open_with("no-db-lock", |p| p.set_paused(true));
    s.core
        .set_archived(&set_archived("conv-01", true, "req-1"))
        .unwrap();
