    let s = Synthetic::open("policy-synthetic-search");
    for query in [
        "ridpath",
        "invoice",
        "budget",
        "from:ana@ridpath.example",
        "ramen",
        "script",
        "xss",
        "restart",
        "nomatchatall",
    ] {
