//! Diagnosis probe: does `list_conversations` contain a conversation
//! immediately after the undo receipt of a CONFIRMED archive, on each backend?
use mail_core::clock::{utc, Clock, FakeClock};
use mail_core::dto::{OperationStatus, SetArchived, UndoOperation};
use mail_core::testing::operations_fake::{ApplyPlan, FakeProvider};
use mail_core::testing::synthetic::{self, *};
use mail_core::testing::{open_core_with_clock, temp_profile, until};
use mail_core::{FakeArchiveProvider, MailCore, ACCOUNT_ID};
use std::sync::Arc;

fn ids(snapshot: &mail_core::dto::InboxSnapshot) -> Vec<String> {
    snapshot.conversations.iter().map(|c| c.conversation_ref.conversation_id.clone()).collect()
}

#[test]
fn synthetic_undo_of_confirmed_archive() {
    let s = Synthetic::open("probe-synth");
    let before = ids(&s.core.list_conversations().unwrap());
    let target = before[1].clone();
    let receipt = s.core.set_archived(&set_archived(&target, true, "a")).unwrap();
    assert!(wait_for_status(&s.core, std::slice::from_ref(&receipt.operation_id), OperationStatus::Confirmed));
    let archived = ids(&s.core.list_conversations().unwrap());
    // Undo with the worker busy-gated: the compensation is queued the moment the receipt returns.
    let undo = s.core.undo_operation(&UndoOperation { operation_id: receipt.operation_id.clone(), request_id: "u".into() }).unwrap();
    let right_after = s.core.list_conversations().unwrap();
    println!("SYNTH before={before:?}\nSYNTH archived={archived:?}\nSYNTH right_after={:?}", ids(&right_after));
    println!("SYNTH comp status right after: {:?}", right_after.activity.iter().map(|a| (a.undo_of.is_some(), a.status)).collect::<Vec<_>>());
    let _ = undo;
    assert_eq!(before, ids(&right_after), "synthetic: same order immediately after undo");
}

#[test]
fn gmail_scripted_undo_of_confirmed_archive() {
    let dir = temp_profile("probe-gmail");
    let clock = Arc::new(FakeClock::new(utc("2026-02-01T00:00:00Z")));
    let mk = |id: &str, at: &str| {
        let m = format!("m-{id}");
        mail_core::testing::thread("acct-probe", id, vec![mail_core::testing::message(&m, "x@example.test", at, "b")], &[m.as_str()], Some(vec![m.clone()]), "h1")
    };
    let provider = FakeProvider::with_threads(vec![mk("c-a", "2026-01-03T00:00:00Z"), mk("c-b", "2026-01-02T00:00:00Z"), mk("c-c", "2026-01-01T00:00:00Z")]);
    let core = open_core_with_clock(dir.path(), &provider, &clock);
    assert!(until(|| core.account_status().is_ok_and(|s| s.sync.initial_sync_complete)));
    core.wait_for_test_idle(mail_core::testing::TIMEOUT).unwrap();
    let before = ids(&core.list_conversations().unwrap());
    let target = before[1].clone();
    let acct = core.account_status().unwrap().account.unwrap().account_id;
    let receipt = core.set_archived(&SetArchived { conversation: mail_core::dto::ConversationRef { account_id: acct.clone(), conversation_id: target.clone() }, archived: true, request_id: "a".into() }).unwrap();
    assert!(until(|| core.list_conversations().unwrap().activity.iter().any(|o| o.id == receipt.operation_id && o.status == OperationStatus::Confirmed)));
    let archived = ids(&core.list_conversations().unwrap());
    provider.set_apply_plan(ApplyPlan::Success);
    core.undo_operation(&UndoOperation { operation_id: receipt.operation_id, request_id: "u".into() }).unwrap();
    let right_after = core.list_conversations().unwrap();
    println!("GMAIL before={before:?}\nGMAIL archived={archived:?}\nGMAIL right_after={:?}", ids(&right_after));
    println!("GMAIL activity right after: {:?}", right_after.activity.iter().map(|a| (a.undo_of.is_some(), a.status)).collect::<Vec<_>>());
    assert_eq!(before, ids(&right_after));
}

