import { describe, expect, it } from 'vitest';
import { effectScope } from 'vue';
import { useMailbox } from '../../src/composables/useMailbox';
import type { MailClient } from '../../src/lib/ipc/client';
import { createBrowserFakeMailClient, fixtureRef, flushMacrotasks } from '../helpers';

/**
 * Diagnosis probe: after `undoLastAction()` resolves, does `conversations`
 * already contain the restored row when a SECOND `mailbox_changed` event
 * (the worker's pass-start event) arrives while the undo's own refresh is in flight?
 */
async function run(extraEvent: boolean): Promise<boolean> {
  const inner = createBrowserFakeMailClient();
  let listener: (() => void) | null = null;
  let armed = false;
  const client: MailClient = {
    ...inner,
    subscribe: async (l) => { listener = l; return inner.subscribe(l); },
    listConversations: () => {
      if (armed && extraEvent) {
        armed = false;
        // The second event lands while the undo's refresh is reading.
        queueMicrotask(() => listener?.());
      }
      return inner.listConversations();
    },
    undoOperation: async (c) => {
      const receipt = await inner.undoOperation(c);
      armed = true;
      return receipt;
    },
  } as MailClient;
  const scope = effectScope();
  const mailbox = scope.run(() => useMailbox(client))!;
  await mailbox.ready;
  mailbox.focusConversation(fixtureRef('conv-01'));
  await mailbox.archiveFocused();
  await inner.controls.flush();
  await flushMacrotasks();
  expect(mailbox.conversations.value.some((c) => c.ref.conversationId === 'conv-01')).toBe(false);
  await mailbox.undoLastAction();
  const presentAtResolve = mailbox.conversations.value.some((c) => c.ref.conversationId === 'conv-01');
  await flushMacrotasks();
  await inner.controls.flush();
  const presentLater = mailbox.conversations.value.some((c) => c.ref.conversationId === 'conv-01');
  console.log(`extraEvent=${extraEvent}: present when undoLastAction resolved=${presentAtResolve}, later=${presentLater}`);
  scope.stop();
  return presentAtResolve;
}

describe('undo refresh probe', () => {
  it('without an extra event the row is present at resolve', async () => {
    expect(await run(false)).toBe(true);
  });
  it('with a second change event during the undo refresh', async () => {
    await run(true);
  });
});
EOF
