    let clock = Arc::new(FakeClock::new(utc("2026-02-01T00:00:00Z")));
    let mk = |id: &str, at: &str| {
        let m = format!("m-{id}");
        mail_core::testing::thread("acct-probe", id, vec![mail_core::testing::message(&m, "x@example.test", at, "b")], &[m.as_str()], Some(vec![m.clone()]), "h1")
    };
    let provider = FakeProvider::with_threads(vec![mk("c-a", "2026-01-03T00:00:00Z"), mk("c-b", "2026-01-02T00:00:00Z")]);
    let core = open_core_with_clock(dir.path(), &provider, &clock);
    assert!(until(|| core.account_status().is_ok_and(|s| s.sync.initial_sync_complete)));
    core.wait_for_test_idle(mail_core::testing::TIMEOUT).unwrap();
    let r = core.set_archived(&SetArchived { conversation: mail_core::dto::ConversationRef { account_id: "acct-probe".into(), conversation_id: "c-b".into() }, archived: true, request_id: "a".into() }).unwrap();
    assert!(until(|| core.list_conversations().unwrap().activity.iter().any(|o| o.id == r.operation_id && o.status == OperationStatus::Confirmed)));
    core.wait_for_test_idle(mail_core::testing::TIMEOUT).unwrap();
    let events = Arc::new(Mutex::new(Vec::new()));
    let sink = events.clone();
    let _sub = core.subscribe(move || sink.lock().unwrap().push(Instant::now()));
    let t0 = Instant::now();
    core.undo_operation(&UndoOperation { operation_id: r.operation_id, request_id: "u".into() }).unwrap();
    let t1 = Instant::now();
    core.wait_for_test_idle(mail_core::testing::TIMEOUT).unwrap();
    timeline("GMAIL", &events, t0, t1);
}
