  const {
    selectedRefs, rangeAnchorRef, selectionNotice, isSelected, toggleSelected, extendSelectionTo,
    selectAllLoaded, clearSelection, intersectSelectionWithLoaded, selectionInLoadedOrder,
  } = useMailboxSelection({ rows: () => conversations.value, targetAvailable: (target) => savedTargetAvailable(target) });

  let readerSource: 'list' | 'activity' = 'list';
  let listToken = 0;
  // Explicit query/navigation ownership must survive routine list refreshes.
  let navigationIntentToken = 0;
  let activityToken = 0;
  let detailToken = 0;
  let commandToken = 0;
  let mailboxSessionToken = 0;
  let detached = false;
  let unsubscribe: (() => void) | null = null;
  let subscriptionAttempt: Promise<void> | null = null;

  // Read-only views of the parent's session counters and the shared command fence;
  // the extracted pieces compare what they captured against these after every await.
  const session: MailboxSession = {
    get generation() { return mailboxSessionToken; },
    get detached() { return detached; },
  };
  const commands: CommandFence = { next: () => ++commandToken, current: () => commandToken };
  const {
    accountStatus, accountState, accountError, accountBusy, mode, isGmail, refreshAccountStatus,
    lastSyncedAt.value = null;
    // Drop every cached surface immediately and invalidate in-flight reads so stale
    // responses cannot repopulate the UI after a disconnect.
    closeReader();
    listToken += 1;
    activityToken += 1;
    activityError.value = null;
    detailToken += 1;
    commandToken += 1;
    mailboxSessionToken += 1;
    inFlightCommandRef.value = null;
    commandInFlight.value = false;
    lastAction.value = null;
    lastGroup.value = null;
    groupInFlight.value = false;
    clearGroupSurfaces();
    clearSelection();
    conversations.value = [];
    activity.value = [];
    // Focus is account-scoped: a new account starts with no conversation focus.
    focusedRef.value = null;
  }

  async function refresh(): Promise<void> {
    if (detached) return;
  window.addEventListener('online', onReconnect);

  onScopeDispose(() => {
    detached = true;
    ++navigationIntentToken;
    void client.cancelSearchMail().catch(() => {});
    listToken += 1;
    activityToken += 1;
    detailToken += 1;
    invalidateDetailCache();
    clearHold();
    unsubscribe?.();
  }

  /** The account identity changed: nothing from the previous account may survive. */
  function resetForAccountChange(): void {
    ++navigationIntentToken;
    ++listToken;
    ++activityToken;
    activityError.value = null;
    ++mailboxSessionToken;
    ++commandToken;
    inFlightCommandRef.value = null;
    expect(slot?.receipt.operationId).toBe('op-0001');
    expect(slot?.undoableUntil).toBeNull();
    expect(slot?.hadWindow).toBe(true);
    stop();
  });

  it('fences new actions during Undo, then permits them after its ownership is released', async () => {
    const fake = createBrowserFakeMailClient();
    const { result, stop } = scopeRun(() => useMailbox(fake));
    await result.ready;
    await result.setArchived(fixtureRef('conv-01'), true);
    expect(result.lastAction.value?.receipt.operationId).toBe('op-0001');
    fake.controls.behavior.holdUndo = true;
    const pendingUndo = result.undoLastAction();
    await flushMacrotasks(1); // let the undo call reach the held fake
    // UX-05 uses a single explicit owner for all mutation entrypoints,
    // including targetless retries and Activity group Undo.
    expect(await result.setArchived(fixtureRef('conv-02'), false)).toBeNull();
    expect(result.lastCommandError.value).toEqual({ kind: 'busy' });
    expect(result.lastAction.value?.receipt.operationId).toBe('op-0001');
    fake.controls.release();
    await pendingUndo;
    expect(result.commandInFlight.value).toBe(false);
    expect(result.lastAction.value?.undone).not.toBeNull();
    await result.setArchived(fixtureRef('conv-02'), false);
    expect(result.lastAction.value?.receipt.operationId).not.toBe('op-0001');
    expect(result.lastAction.value?.undone).toBeNull();
    stop();
  });
});

