        listener = l;
        return fake.subscribe(l);
      },
      // Real IPC reads take time.
      listConversations: async () => {
        if (armed) {
          armed = false;
          queueMicrotask(() => listener?.()); // the worker's pass-start event
        }
        await new Promise((resolve) => setTimeout(resolve, 5));
        return fake.listConversations();
      },
