    let snapshot = s.core.list_conversations().unwrap();
    let read: Vec<&str> = snapshot
        .conversations
        .iter()
        .filter(|c| c.is_read == Some(true))
        .map(|c| c.conversation_ref.conversation_id.as_str())
        .collect();
    let mut read_sorted = read.clone();
